parameters.jsCode:
const j = $input.item.json;
const trig = $('Application Form').itemMatching($itemIndex);
const bin = ($input.item.binary && Object.keys($input.item.binary).length) ? $input.item.binary : (trig.binary || {});
const key = Object.keys(bin)[0];
const s = (v) => String(v == null ? '' : v).trim();

const first = s(j['First Name']), last = s(j['Last Name']);
const name = (first + ' ' + last).trim() || 'Candidate';
const email = s(j['Email']).toLowerCase();
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);
const exp = Number(j['Years of experience']);
const consentRaw = j['Consent'];
const consent = Array.isArray(consentRaw) ? consentRaw.length > 0 : !!consentRaw;
const submittedAt = s(j.submittedAt) || new Date().toISOString();
const applicationId = 'APP-' + submittedAt.slice(0, 10).replace(/-/g, '') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
const canAck = emailValid && !/no-?reply|do-?not-?reply|mailer-daemon|postmaster/i.test(email);

const out = {
  json: {
    hrEmail: j.hrEmail, companyName: j.companyName, jobTitle: j.jobTitle, jobDescription: j.jobDescription,
    mustHaves: j.mustHaves, shortlistScore: j.shortlistScore, reviewScore: j.reviewScore, channelMinScore: j.channelMinScore,
    schedulingLink: j.schedulingLink, sendAck: j.sendAck,
    slackWebhookUrl: j.slackWebhookUrl, teamsWebhookUrl: j.teamsWebhookUrl, webhookUrl: j.webhookUrl,
    applicationId, submittedAt, candidateName: name, firstName: first, candidateEmail: email, emailValid, canAck,
    phone: s(j['Phone']), experienceYears: isNaN(exp) ? null : exp,
    location: s(j['Current location']), profileLink: s(j['LinkedIn or portfolio link']),
    coverNote: s(j['Cover note']).slice(0, 1500), consent,
    cvFileName: key ? name.replace(/[^A-Za-z0-9]+/g, '_') + '_CV.pdf' : ''
  }
};
if (key) { const b = Object.assign({}, bin[key]); b.fileName = out.json.cvFileName; out.binary = { data: b }; }
return out;

const p = $('Prepare Application').itemMatching($itemIndex);
const text = String($input.item.json.text || '').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
const out = { json: Object.assign({}, p.json, { cvText: text.slice(0, 12000), cvReadable: text.length >= 200 }) };
if (p.binary && Object.keys(p.binary).length) out.binary = p.binary;
return out;

parameters.message:
=Manual CV review needed

Application: {{ $json.applicationId }}
Candidate: {{ $json.candidateName }} ({{ $json.candidateEmail }})
Phone: {{ $json.phone }}
Role: {{ $json.jobTitle }}

Why: the CV PDF has no readable text. It may be a scanned image or password protected. The original file is attached, please review it manually.

No AI score was produced for this application.

parameters.jsCode:
const m = $('Merge CV Text').itemMatching($itemIndex);
const c = m.json;
const ai = $input.item.json.output || null;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

let score = null, decision = 'MANUAL REVIEW';
if (ai && typeof ai.score === 'number') {
  score = Math.max(0, Math.min(100, Math.round(ai.score)));
  decision = score >= Number(c.shortlistScore) ? 'SHORTLIST' : score >= Number(c.reviewScore) ? 'REVIEW' : 'NOT A MATCH';
}
const style = {
  'SHORTLIST': { color: '#188038', emoji: '🌟' },
  'REVIEW': { color: '#e8710a', emoji: '🟠' },
  'NOT A MATCH': { color: '#d93025', emoji: '🔴' },
  'MANUAL REVIEW': { color: '#5f6368', emoji: '⚠️' }
}[decision];

const li = (arr, f) => (arr && arr.length ? arr.map(f).join('') : '<li>None</li>');
const icon = { met: '✅', partial: '🟡', not_met: '❌' };
const mustRows = ai && ai.mustHaves && ai.mustHaves.length
  ? ai.mustHaves.map((x) => '<tr><td style="padding:6px 8px;border-bottom:1px solid #eee">' + (icon[x.status] || '•') + ' ' + esc(x.requirement) + '</td><td style="padding:6px 8px;border-bottom:1px solid #eee;color:#555">' + esc(x.evidence) + '</td></tr>').join('')
  : '<tr><td style="padding:6px 8px" colspan="2">No must-have requirements were set.</td></tr>';

const body = ai
  ? '<h3 style="margin:18px 0 4px">Summary</h3><p style="margin:0">' + esc(ai.summary) + '</p>' +
    '<p style="margin:10px 0 0"><b>Current role:</b> ' + esc(ai.currentRole) + ' &nbsp;|&nbsp; <b>Experience (CV):</b> ~' + esc(ai.yearsExperience) + ' yrs &nbsp;|&nbsp; <b>Stated:</b> ' + esc(c.experienceYears == null ? 'n/a' : c.experienceYears) + ' yrs<br><b>Experience check:</b> ' + esc(ai.experienceCheck) + '<br><b>Top skills:</b> ' + esc((ai.topSkills || []).join(', ')) + '</p>' +
    '<h3 style="margin:18px 0 4px">Must-have check</h3><table style="width:100%;border-collapse:collapse;font-size:13px">' + mustRows + '</table>' +
    '<h3 style="margin:18px 0 4px">Strengths</h3><ul style="margin:0">' + li(ai.strengths, (s) => '<li><b>' + esc(s.title) + ':</b> ' + esc(s.evidence) + '</li>') + '</ul>' +
    '<h3 style="margin:18px 0 4px">Gaps and concerns</h3><ul style="margin:0">' + li(ai.gaps, (g) => '<li><b>' + esc(g.title) + ':</b> ' + esc(g.detail) + '</li>') + '</ul>' +
    '<h3 style="margin:18px 0 4px">Phone-screen question kit</h3><ol style="margin:0">' + li(ai.interviewQuestions, (q) => '<li>' + esc(q) + '</li>') + '</ol>'
  : '<p>The AI service was unavailable, so no automatic score was produced. Please review the attached CV manually.</p>';

const bar = score === null ? '' :
  '<div style="background:rgba(255,255,255,.35);border-radius:6px;height:10px;margin-top:10px"><div style="width:' + score + '%;background:#fff;height:10px;border-radius:6px"></div></div>';

const reportHtml =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:700px;margin:auto;border:1px solid #ddd;border-radius:10px;overflow:hidden">' +
  '<div style="background:' + style.color + ';color:#fff;padding:18px 22px"><div style="font-size:12px;letter-spacing:1px">AI APPLICATION SCORECARD | ' + esc(c.jobTitle).toUpperCase() + '</div>' +
  '<div style="font-size:26px;font-weight:bold;margin-top:4px">' + style.emoji + ' ' + decision + (score === null ? '' : ': ' + score + '/100') + '</div>' + bar + '</div>' +
  '<div style="padding:20px 22px;color:#222;font-size:14px;line-height:1.5">' +
  '<p style="margin-top:0"><b>Application ID:</b> ' + esc(c.applicationId) + ' &nbsp;|&nbsp; <b>Received:</b> ' + esc(c.submittedAt) + '<br>' +
  '<b>Candidate:</b> ' + esc(c.candidateName) + '<br><b>Email:</b> ' + esc(c.candidateEmail) + ' &nbsp;|&nbsp; <b>Phone:</b> ' + esc(c.phone) + '<br>' +
  '<b>Location:</b> ' + esc(c.location || 'n/a') + ' &nbsp;|&nbsp; <b>Profile:</b> ' + esc(c.profileLink || 'n/a') + '<br>' +
  '<b>CV:</b> attached (' + esc(c.cvFileName) + ')</p>' + body + '</div>' +
  '<div style="background:#f5f5f5;color:#777;padding:10px 22px;font-size:12px">AI-assisted screening on job-relevant criteria only. Applicant consent recorded: ' + (c.consent ? 'yes' : 'NO') + '. A human must make the final hiring decision.</div></div>';

const company = esc(c.companyName), job = esc(c.jobTitle);
const first = esc(c.firstName);
const ackHtml =
  '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6;color:#222">' +
  '<p>Hello' + (first ? ' ' + first : '') + ',</p>' +
  '<p>Thank you for applying for the <b>' + job + '</b> position at ' + company + '. We have received your application (reference <b>' + esc(c.applicationId) + '</b>) and our hiring team will review it carefully.</p>' +
  '<p>If your profile matches what we are looking for, we will contact you about the next steps. Your data is used only for this recruitment process.</p>' +
  '<p>Best regards,<br>' + company + ' Talent Team</p></div>';

const link = c.schedulingLink ? '<a href="' + esc(c.schedulingLink) + '">' + esc(c.schedulingLink) + '</a>' : '[ADD YOUR SCHEDULING LINK OR PROPOSED TIMES]';
const strength = ai && ai.strengths && ai.strengths[0] ? '<p>Your background stood out to us, in particular: <i>' + esc(ai.strengths[0].title) + '</i>.</p>' : '';
const inviteHtml =
  '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.6;color:#222">' +
  '<p>Hello' + (first ? ' ' + first : '') + ',</p>' +
  '<p>Thank you for applying for the <b>' + job + '</b> position at ' + company + ' and for the time you put into your application.</p>' + strength +
  '<p>We would like to invite you to a short introductory phone call. Please choose a time that suits you here: ' + link + '</p>' +
  '<p>If you have any questions beforehand, just reply to this email.</p>' +
  '<p>Best regards,<br>' + company + ' Talent Team</p></div>';

const summaryText = ai ? ai.summary : 'AI unavailable. Manual review needed.';
const webhookPayload = {
  event: 'candidate.screened', applicationId: c.applicationId, submittedAt: c.submittedAt,
  job: { title: c.jobTitle, company: c.companyName },
  candidate: { name: c.candidateName, email: c.candidateEmail, phone: c.phone, location: c.location, profileLink: c.profileLink, statedExperienceYears: c.experienceYears },
  screening: { decision, score, aiAvailable: !!ai, summary: summaryText, strengths: ai ? ai.strengths : [], gaps: ai ? ai.gaps : [], mustHaves: ai ? ai.mustHaves : [] },
  humanReviewRequired: true
};

const outBin = m.binary && Object.keys(m.binary).length ? m.binary : undefined;
const result = { json: {
  hrEmail: c.hrEmail, decision, score, isShortlisted: decision === 'SHORTLIST', aiAvailable: !!ai,
  subjectLine: style.emoji + ' ' + decision + (score === null ? '' : ' (' + score + '/100)') + ': ' + c.candidateName + ' | ' + c.jobTitle,
  reportHtml,
  candidateEmail: c.candidateEmail, canAck: c.canAck, sendAck: c.sendAck === true || c.sendAck === 'true',
  ackSubject: 'We received your application: ' + c.jobTitle, ackHtml,
  inviteSubject: 'Invitation to a phone call: ' + c.jobTitle + ' at ' + c.companyName, inviteHtml,
  applicationId: c.applicationId, submittedAt: c.submittedAt, candidateName: c.candidateName, phone: c.phone,
  experienceYears: c.experienceYears, jobTitle: c.jobTitle, companyName: c.companyName, cvFileName: c.cvFileName, summaryText,
  channelMinScore: c.channelMinScore, slackWebhookUrl: c.slackWebhookUrl, teamsWebhookUrl: c.teamsWebhookUrl, webhookUrl: c.webhookUrl,
  emoji: style.emoji, webhookPayload
} };
if (outBin) result.binary = outBin;
return result;

const out = [];
for (const item of $input.all()) {
  const d = item.json;
  const passes = d.score === null || d.score === undefined || Number(d.score) >= Number(d.channelMinScore);
  if (!passes) continue;
  const scoreTxt = d.score === null || d.score === undefined ? '' : ' (' + d.score + '/100)';
  const headline = d.emoji + ' ' + d.decision + scoreTxt + ': ' + d.candidateName + ' for ' + d.jobTitle;
  const ok = (u, re) => typeof u === 'string' && re.test(u.trim());

  if (ok(d.slackWebhookUrl, /^https:\/\/hooks\.slack\.com\//i)) {
    out.push({ json: { channel: 'slack', url: d.slackWebhookUrl.trim(), body: { text: '*' + headline + '*\n' + d.summaryText + '\n_Application ' + d.applicationId + '. Full scorecard and CV were emailed to HR._' } } });
  }
  if (ok(d.teamsWebhookUrl, /^https:\/\//i)) {
    out.push({ json: { channel: 'teams', url: d.teamsWebhookUrl.trim(), body: {
      type: 'message',
      attachments: [{ contentType: 'application/vnd.microsoft.card.adaptive', contentUrl: null, content: {
        '$schema': 'http://adaptivecards.io/schemas/adaptive-card.json', type: 'AdaptiveCard', version: '1.4',
        body: [
          { type: 'TextBlock', text: headline, weight: 'Bolder', size: 'Medium', wrap: true },
          { type: 'FactSet', facts: [
            { title: 'Application', value: d.applicationId },
            { title: 'Decision', value: d.decision + scoreTxt },
            { title: 'Candidate', value: d.candidateName } ] },
          { type: 'TextBlock', text: d.summaryText, wrap: true },
          { type: 'TextBlock', text: 'Full scorecard and CV were emailed to HR. A human makes the final decision.', isSubtle: true, wrap: true }
        ] } }]
    } } });
  }
  if (ok(d.webhookUrl, /^https:\/\//i)) {
    out.push({ json: { channel: 'webhook', url: d.webhookUrl.trim(), body: d.webhookPayload } });
  }
}
return out;
